struct Tally {
    total: Int,
    count: Int,
}

fn record(mut t: Tally, take value: Int) -> () {
    t.total = t.total + value;
    t.count = t.count + 1;
}

fn mean_of_three(take a: Int, take b: Int, take c: Int) -> Int {
    var t = Tally { total: 0, count: 0 };
    record(t, a);
    record(t, b);
    record(t, c);
    t.total / t.count
}

spec mean_of_three {
    then mean_of_three(1, 2, 3) == 2;
    then mean_of_three(10, 10, 11) == 10;
}

enum Dir {
    North,
    South,
    East,
    West,
}

fn code(take d: Dir) -> Int {
    match d {
        Dir::North => 0,
        Dir::East => 1,
        Dir::South => 2,
        Dir::West => 3,
    }
}

fn turn_right(take d: Dir) -> Dir {
    match d {
        Dir::North => Dir::East,
        Dir::East => Dir::South,
        Dir::South => Dir::West,
        Dir::West => Dir::North,
    }
}

spec turn_right {
    then code(turn_right(Dir::North)) == 1;
    then code(turn_right(Dir::West)) == 0;
}

fn dot(take a: [Int; 3], take b: [Int; 3]) -> Int {
    var acc = 0;
    for i in 0 .. 3 {
        acc = acc + a[i] * b[i];
    }
    acc
}

spec dot {
    then dot([1, 2, 3], [4, 5, 6]) == 32;
    then dot([0, 0, 0], [1, 2, 3]) == 0;
}

fn square(take n: Int) -> Int {
    n * n
}

spec square {
    then square(0) == 0;
    then square(5) == 25;
    then square(-4) == 16;
}

fn first_or_zero() -> Int {
    var xs = std::array::empty();
    std::array::push(xs, 42);
    std::array::get(xs, 0)
}

spec first_or_zero {
    then first_or_zero() == 42;
}

fn most_common(in xs: [Int; 6]) -> Int {
    var counts = std::map::empty();
    var best = xs[0];
    var best_count = 0;
    for x in xs {
        let seen = match std::map::get(counts, x) {
            Some { value } => value,
            None => 0,
        };
        let _ = std::map::insert(counts, x, seen + 1);
        if seen + 1 > best_count {
            best = x;
            best_count = seen + 1;
        }
    }
    best
}

spec most_common {
    then most_common([1, 2, 2, 3, 3, 3]) == 3;
    then most_common([4, 4, 5, 5, 6, 6]) == 4;
}

