fn sign(take n: Int) -> Int {
    if n < 0 {
        0 - 1
    } else if n > 0 {
        1
    } else {
        0
    }
}

spec sign {
    then sign(-8) == 0 - 1;
    then sign(0) == 0;
    then sign(99) == 1;
}

fn power(take base: Int, take exp: Int) -> Int {
    var result = 1;
    var i = 0;
    while i < exp {
        result = result * base;
        i = i + 1;
    }
    result
}

spec power {
    then power(2, 0) == 1;
    then power(2, 10) == 1024;
    then power(5, 3) == 125;
}

fn parse_flag(take n: Int) -> Result[Int, Str] {
    if n == 0 {
        Ok { value: 0 }
    } else if n == 1 {
        Ok { value: 1 }
    } else {
        Err { error: "not a flag" }
    }
}

fn or_neg1(in r: Result[Int, Str]) -> Int {
    match r {
        Ok { value } => value,
        Err { error } => 0 - 1,
    }
}

spec parse_flag {
    then or_neg1(parse_flag(1)) == 1;
    then or_neg1(parse_flag(9)) == 0 - 1;
}

fn reversed(in s: Str) -> String {
    var out = std::string::empty();
    var i = std::str::len(s) - 1;
    while i >= 0 {
        std::string::push_byte(out, std::str::byte_at(s, i));
        i = i - 1;
    }
    out
}

spec reversed {
    then std::string::as_str(reversed("abc")) == "cba";
}

heldout_specs:
spec "reversed edge cases" {
    then std::string::len(reversed("")) == 0;
    then std::string::as_str(reversed("a")) == "a";
    then std::string::as_str(reversed("racecar")) == "racecar";
}

